function openWorkspaceItem(ref){
  if(!ref)return;if(ref.kind==='document'){openDocument(ref.id);return}
  if(ref.kind==='note'||ref.kind==='highlight'){
    const note=data.notes.find(note=>note.id===ref.id);if(!note){notify('This note is no longer in the workspace');return}
    if(ref.passage){const sourceId=note.selectionSourceId||note.sourceId||ref.sourceId;if(sourceId&&data.docs.some(doc=>doc.id===sourceId)){if(!note.selectionSourceId&&!note.sourceId){note.sourceId=sourceId;save()}jumpToSavedSelection(note.id);return}}
    noteFolder='All notes';noteFavorites=false;noteRecent=false;noteArchived=!!note.archived;query='';byId('search').value='';view='notes';data.selected={type:'note',id:note.id};render();return;
  }
  if(ref.kind==='board'){if(!data.boards.some(board=>board.id===ref.id)){notify('This board is no longer in the workspace');return}data.activeBoard=ref.id;view='board';data.selected=null;boardSelection.clear();render();}
}
function openWorkspaceView(target,options={}){
  if(target==='tasks'||target==='templates'){view='home';data.selected=null;render();return}
  if(view==='reader')saveReaderProgress();data.selected=null;
  if(target==='notes'){noteFolder=options.folder||'All notes';noteFavorites=false;noteRecent=false;noteArchived=false;query='';byId('search').value='';}
  if(target==='library'){libraryFolder=options.folder||'All documents';libraryType=options.type||'all';libraryFavorites=false;librarySmart='all';libraryTag='';query='';byId('search').value='';documentLibrary.resetSearch();}
  if(target==='projects'&&options.folder){view='projects';workspaceOrganizer.openProject(options.folder);render();return}
  view=target;render();
}
function beginProjectSetup(openAfter='project'){
  view='projects';data.selected=null;query='';
  const search=byId('search');if(search)search.value='';
  workspaceOrganizer.startProject({openAfter});render();
  document.querySelector('[data-ps-form] input[name="name"]')?.focus();
}
async function persistWorkspaceNote(note){
  const project=data.folderProjects?.[note.folder];if(!project||window.NotejectWebApp)return;
  const response=await fetch(diskApiBase+'/api/project-notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project,id:note.id,title:note.title,content:note.content})});
  if(!response.ok)throw Error('Saved in noteject, but the project note file could not be updated');
}
