function setNoteColor(noteId,color){
 const note=data.notes.find(item=>item.id===noteId);
 if(!note||!['violet','blue','teal','amber','rose','gray'].includes(color))return false;
 if(storageRecovery){notify('Cannot save the note color while workspace recovery is active');return false}
 const previous=note.color;note.color=color;
 if(!save()||!workspaceStore.flush()){
  if(previous===undefined)delete note.color;else note.color=previous;
  notify('Could not save the note color');return false;
 }
 document.querySelectorAll('.note-list-card[data-note]').forEach(card=>{if(card.dataset.note===noteId)card.dataset.color=color});
 document.querySelectorAll('select[data-note-color]').forEach(control=>{if(control.dataset.noteColor===noteId)control.value=color});
 document.querySelectorAll('button[data-note-color-choice]').forEach(control=>{if(control.dataset.noteColorId===noteId)control.setAttribute('aria-pressed',String(control.dataset.noteColorChoice===color))});
 return true;
}
let fileDbPromise, attachmentMutationEpoch=0, attachmentMutationsInFlight=0;
async function mutateAttachment(run){attachmentMutationEpoch++;attachmentMutationsInFlight++;try{return await run()}finally{attachmentMutationEpoch++;attachmentMutationsInFlight--}}
function fileDb(){
 if(!fileDbPromise)fileDbPromise=new Promise((resolve,reject)=>{
  const req=indexedDB.open('noteject-files',2);
  req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('documents'))req.result.createObjectStore('documents');if(!req.result.objectStoreNames.contains('imports'))req.result.createObjectStore('imports',{keyPath:'id'})};
  req.onsuccess=()=>{req.result.onversionchange=()=>{req.result.close();fileDbPromise=null};resolve(req.result)};req.onerror=()=>{fileDbPromise=null;reject(req.error)};
 });return fileDbPromise;
}
const attachmentImports=window.NotejectAttachmentImports.create({database:fileDb,storage:localStorage,workspace:()=>data});
async function storeFile(docId,blob){return mutateAttachment(async()=>{await attachmentImports.recover();const db=await fileDb();return new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').put(blob,attachmentImports.resolve(docId));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})})}
async function getStoredFile(docId,blobKey=attachmentImports.resolve(docId)){await attachmentImports.recover();const db=await fileDb();return new Promise((resolve,reject)=>{const req=db.transaction('documents').objectStore('documents').get(blobKey);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
