 if(window.NotejectWebApp){if(storageError)throw Error(`Browser storage could not open “${doc?.name||'this file'}”. Reload the page and try again. If it continues, restore a workspace backup from a device that has the original file.`);return null}
 if(doc?.diskProject){const response=await fetch(attachmentUrl(doc));if(!response.ok)throw Error(`Could not load file from project storage (HTTP ${response.status}).`);return response.blob()}
