function graphFitView(){const all=allGraphNodes(),edges=allGraphEdges(),degree=new Map(all.map(node=>[node.id,0]));edges.forEach(edge=>{degree.set(edge.from,(degree.get(edge.from)||0)+1);degree.set(edge.to,(degree.get(edge.to)||0)+1)});const term=graphQuery.trim().toLowerCase(),nodes=all.filter(node=>(graphType==='all'||(graphType==='notes'?node.type==='note':node.type==='doc'))&&(!graphConnectedOnly||degree.get(node.id)>0)&&(!term||(node.label+' '+node.detail).toLowerCase().includes(term))),visible=new Set(nodes.map(node=>node.id)),positions=graphPositions(nodes,edges.filter(edge=>visible.has(edge.from)&&visible.has(edge.to)));if(!nodes.length){graphZoom=1;graphPan={x:0,y:0};return}const points=[...positions.values()],left=Math.min(...points.map(point=>point.x))-55,right=Math.max(...points.map(point=>point.x))+55,top=Math.min(...points.map(point=>point.y))-62,bottom=Math.max(...points.map(point=>point.y))+70,width=Math.max(1,right-left),height=Math.max(1,bottom-top),canvas=document.querySelector('.graph-canvas'),rect=canvas?.getBoundingClientRect(),viewBox=graphViewSize(canvas),scale=rect?.width>0&&rect?.height>0?Math.min(rect.width/viewBox.width,rect.height/viewBox.height):1,fitWidth=rect?.width>0?Math.max(1,(rect.width-32)/scale):1060,fitHeight=rect?.height>0?Math.max(1,(rect.height-100)/scale):640;graphZoom=Math.max(.05,Math.min(4,Math.min(fitWidth/width,fitHeight/height)));graphPan={x:viewBox.width/2-(left+width/2)*graphZoom,y:(viewBox.height-40)/2-(top+height/2)*graphZoom}}function graphTransform(){return `translate(${graphPan.x} ${graphPan.y}) scale(${graphZoom})`}
