function openSmartSource(source){
  if(source.kind==='document'){if(data.docs.some(doc=>doc.id===source.id))openDocument(source.id);else notify('This file is no longer in the library');return}
  if(source.kind==='note'){
    const note=data.notes.find(item=>item.id===source.id);if(!note){notify('This note is no longer in the library');return}
    if(note.selectionSourceId||note.sourceId){jumpToSavedSelection(note.id);return}
    view='notes';data.selected={type:'note',id:note.id};render();return;
  }
  const board=data.boards.find(item=>item.id===(source.boardId||source.id));
  if(!board){notify('This board is no longer in the workspace');return}
  data.activeBoard=board.id;view='board';data.selected=null;boardSelection.clear();render();
  if(source.kind==='connection'){const edge=(board.edges||[]).find(item=>(item.id||item.from+'-'+item.to)===source.id);if(edge?.id)connectionEditor.open(edge.id)}
}
function saveSmartAnswer(question,answer,sources=[]){
  const refs=sources.filter(source=>source&&['note','document','board','connection'].includes(source.kind)&&typeof source.id==='string').map(source=>({kind:source.kind,id:source.id,boardId:source.boardId,title:String(source.title||'Source'),type:source.type,folder:source.folder}));
  const title=('Smart: '+String(question||'Workspace review').trim()).slice(0,120);
  const content='## Question\n\n'+String(question||'Workspace review')+'\n\n## Answer\n\n'+String(answer||'')+(refs.length?'\n\n## Sources\n\n'+refs.map((source,i)=>'- [S'+(i+1)+'] '+source.title).join('\n'):'');
  const note={id:id(),title,content,smartSources:refs,updated:Date.now(),created:Date.now(),folder:'Inbox',tags:['smart-engine'],favorite:false,archived:false,color:'violet'};
  data.notes.unshift(note);data.noteFolders=data.noteFolders||['Inbox'];data.folders=data.folders||['Inbox'];
  if(!data.noteFolders.includes('Inbox'))data.noteFolders.unshift('Inbox');if(!data.folders.includes('Inbox'))data.folders.unshift('Inbox');
  query='';byId('search').value='';noteFolder='Inbox';noteFavorites=false;noteRecent=false;noteArchived=false;view='notes';data.selected={type:'note',id:note.id};save();render();notify('Smart result saved to All Notes');
  const project=data.folderProjects?.[note.folder];if(project&&!window.NotejectWebApp)fetch(diskApiBase+'/api/project-notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project,id:note.id,title:note.title,content:note.content})}).then(response=>{if(!response.ok)throw Error('Result saved locally; the project note file could not be saved')}).catch(error=>notify(error.message));
}
