  const tr=value=>window.NotejectI18n?.t?.(value)||value;
  const message=tr('Move board to Trash?')+' “'+board.name+'”. '+tr('You can restore it later.')+(data.boards.length===1?' '+tr('A fresh empty board will be created.'):'');
