function boardAssetOrigin(board,point=null){
  const world=window.NotejectBoardScene.worldSize([],undefined,board.worldFrame);
  return{x:world.width/2,y:world.height/2};
}
function boardAssetPosition(board,origin,index=0){
  board.focusNewAssets=true;board.organizeNewAssets=true;
  for(let slot=index;slot<index+(board.items?.length||0)*4+12;slot++){
    const x=Math.max(40,Math.round(origin.x-207/2)+(slot%3)*230),y=Math.max(40,Math.round(origin.y-80)+Math.floor(slot/3)*190);
    if(!(board.items||[]).some(item=>x<item.x+223&&x+223>item.x&&y<item.y+176&&y+176>item.y))return{x,y};
  }
  return{x:Math.max(40,...(board.items||[]).map(item=>item.x+230)),y:Math.max(40,origin.y-80)};
}
function placeDocumentsOnBoard(docIds,boardId,point=null){
  const board=data.boards.find(item=>item.id===boardId);
  if(!board)return;
  const docs=[...new Set(docIds)].map(docId=>data.docs.find(doc=>doc.id===docId)).filter(Boolean);
  if(!docs.length)return;
  board.items||=[];
  const existing=new Set(board.items.map(item=>item.id)),added=[];
  const origin=boardAssetOrigin(board,point);
  for(const doc of docs){
    if(existing.has(doc.id))continue;
    board.items.push({type:'doc',id:doc.id,...boardAssetPosition(board,origin,added.length)});
    existing.add(doc.id);added.push(doc.id);
  }
  data.activeBoard=boardId;view='board';data.selected=null;save();render();
  notify(added.length?'Added '+added.length+' document'+(added.length===1?'':'s')+' to '+board.name:'Document'+(docs.length===1?' is':'s are')+' already on this board');
}
