 const board=data.boards.find(item=>item.id===boardId);if(!board)return;
 const notes=[...new Set(noteIds)].map(id=>data.notes.find(note=>note.id===id)).filter(Boolean);if(!notes.length)return;
 board.items||=[];const existing=new Set(board.items.map(item=>item.id)),added=notes.filter(note=>!existing.has(note.id)),origin=boardAssetOrigin(board,point);
 added.forEach((note,index)=>board.items.push({type:'note',id:note.id,...boardAssetPosition(board,origin,index)}));
 data.activeBoard=boardId;view='board';data.selected=null;save();render();
