  if(isPagedReaderDoc(doc)&&pdfDoc?.documentId===documentId){const state=pdfDoc;state.indexConsumers.add('assistant');try{await ensurePdfTextIndex(doc,state,token)}finally{state.indexConsumers.delete('assistant')}if(token!==readerLoadToken||state!==pdfDoc)throw Error('This document is no longer open.');}
