async function restorePreviousWorkspace(){
 const snapshot=await attachmentImports.previous();if(!snapshot){notify('No previous imported workspace is available.');return}
 if(!await NotejectDialogs.confirm('Restore the workspace saved before your last import? The current workspace will become the recovery snapshot.',{title:'Recover previous workspace',confirmLabel:'Restore workspace'}))return;
 if(!storageRecovery&&!workspaceStore.flush()){notify('Could not save the current workspace.');return}
 const previous=data,previousRecovery=storageRecovery;let session,published=false;
 try{
  session=await attachmentImports.begin();const restored=JSON.parse(snapshot.previousWorkspace);restored.attachmentImportId=session.id;restored.selected=null;
  await resetImportedTextIndexes(restored.docs);
  if(!previousRecovery&&!workspaceStore.flush())throw Error('Could not save the current workspace.');
  await attachmentImports.checkpoint(session);
  data=restored;storageRecovery=null;workspaceStore.schedule();if(!workspaceStore.flush())throw Error('Could not save the recovered workspace.');published=true;
  await attachmentImports.commit(session);view='home';render();await hydrateSearchIndex();smartEngine.refresh();notify('Previous workspace recovered.');
 }catch(error){if(!published){data=previous;storageRecovery=previousRecovery;if(session)await attachmentImports.abort(session).catch(()=>{})}notify(error.message)}
}
if(window.NotejectAndroid)attachmentImports.recover().then(count=>{if(count)notify('An interrupted import was cleaned up. Your workspace was kept.');}).catch(error=>notify('Attachment recovery could not finish: '+error.message));

async function resetImportedTextIndexes(documents){
 searchTextCache.clear();
 for(const doc of documents){delete doc.nativeTextIndexKey;delete doc.nativeTextIndexPages;delete doc.nativeTextIndexComplete;delete doc.searchTextVersion;delete doc.searchTextEmpty;}
 try{const db=await searchIndexDb();await new Promise((resolve,reject)=>{const tx=db.transaction('texts','readwrite');for(const doc of documents)tx.objectStore('texts').delete(doc.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});}catch{}
}
